def typed_dict_from_dict(d: TypeDict) ->type:
    module = d["module"]
    qualname = d["qualname"]
    elem_types = d["elem_types"]
    name_in_module = get_name_in_module(module, qualname)
    annotations = {k: type_from_dict(v) for k, v in elem_types.items()}
